<script setup lang="ts">
import { computed, ref } from 'vue'
import { useCatalogue, provenance } from './catalogue'
import { saved, guestName, alerts, toggleSaved } from './preferences'
const props = defineProps<{ section: string }>(); defineEmits<{ close: [] }>()
const { data, error, retry, loading } = useCatalogue(() => props.section)
const name = ref(guestName.value); const message = ref('')
function alertEnabled(name: string) { return /kickoff/i.test(name) ? alerts.value.kickoff : /final|score|result/i.test(name) ? alerts.value.results : true }
const sourceTitle = computed(() => ({ favourites: 'Featured watchlist', alerts: 'Alert previews', account: 'Profile examples' })[props.section])
function rename() { const next = name.value.trim(); if (!next) return; guestName.value = next.slice(0, 32); message.value = 'Guest name saved on this device.' }
</script>
<template><div class="utility-desk"><template v-if="section === 'favourites'"><p>Save a record from any catalogue to keep it on this device.</p><ul v-if="saved.length" class="saved-list"><li v-for="entry in saved" :key="entry.section + entry.record.id"><RouterLink :to="{path:'/' + entry.section,query:{record:entry.record.id}}" @click="$emit('close')">{{ entry.record.name }} ↗</RouterLink><small>{{ provenance(entry.mode) }}</small><button :aria-label="'Remove ' + entry.record.name" @click="toggleSaved(entry.section,entry.record,entry.mode)">Remove</button></li></ul><RouterLink to="/clubs" class="text-link" @click="$emit('close')">Find a club to follow ↗</RouterLink></template><template v-if="section === 'alerts'"><p>Choose which example alerts to highlight. Preferences stay on this device; these do not send notifications.</p><label class="preference-check"><input v-model="alerts.kickoff" type="checkbox"> Kickoff reminders</label><label class="preference-check"><input v-model="alerts.results" type="checkbox"> Final scores</label><small>{{ Number(alerts.kickoff) + Number(alerts.results) }} preview categories selected</small></template><form v-if="section === 'account'" @submit.prevent="rename"><label class="search-label" for="guest-name">Guest display name</label><input id="guest-name" v-model="name" class="search-input" required maxlength="32" autocomplete="off"><button class="ui-button ui-button--secondary">Save name</button><p role="status">{{ message || 'A local guest profile; no sign-in required.' }}</p></form><section class="utility-samples"><h3>{{ sourceTitle }}</h3><p v-if="loading" role="status">Loading examples…</p><p v-else-if="error">{{ error }} <button class="text-link" @click="retry">Retry</button></p><template v-else-if="data"><span class="demo-label">{{ provenance(data.mode) }}</span><ul class="rail-items"><li v-for="row in data.items" :key="row.id"><strong>{{ row.name }}</strong><span>{{ row.detail }}</span><small>{{ row.value }}<template v-if="section === 'alerts'"> · {{ alertEnabled(row.name) ? 'Preview enabled' : 'Preview muted' }}</template></small></li></ul></template></section></div></template>
